package org.springframework.samples.petclinic.rest.controller;

/**
 * Thrown when creating an owner whose normalized telephone is already used by another
 * owner. Handled as {@code 409 Conflict}.
 */
public class DuplicateTelephoneException extends RuntimeException {

    public DuplicateTelephoneException(String telephone) {
        super("telephone is already used by another owner (value: " + telephone + ")");
    }
}

